const {briefing}= $json;
const supported=[
 ['fazenda',/^https:\/\/(?:www\.)?gov\.br\/fazenda\/pt-br\/(?:assuntos\/noticias|central-de-conteudo|acesso-a-informacao\/acoes-e-programas)\/[A-Za-z0-9/_-]+\/?$/i,'Ministério da Fazenda'],
 ['tesouro',/^https:\/\/www\.tesourotransparente\.gov\.br\/(?:publicacoes|temas)\/[A-Za-z0-9/_-]+\/?$/i,'Tesouro Nacional'],
 ['planalto',/^https:\/\/(?:www\.)?planalto\.gov\.br\/ccivil_03\/[A-Za-z0-9/_.-]+\.htm$/i,'Presidência da República']
];
const original=[briefing.source.url,...(briefing.source.text.match(/https:\/\/[^\s<>"']+/g)??[])].slice(0,30);
const links=[...new Set(original.map(url=>url.split(/[?#]/,1)[0].replace(/[),.;]+$/,'')))];
for(const [id,pattern,publisher] of supported){
 const url=links.find(value=>pattern.test(value)&&!value.split('/').some(part=>part==='..'||part==='.'));
 if(url) return {json:{briefing,economic_source:{id,url,publisher,kind:'documento'}}};
}
const subject=[briefing.source.title,briefing.question].join(' ');
const selic=/\b(?:Selic|Copom)\b/i.test(subject);
const ipca=/\bIPCA\b(?![-\s]?15\b)/i.test(subject)&&!/\bIPCA[-\s]?15\b/i.test(subject);
if(selic===ipca) return {json:{briefing,economic_source:null}};
const end = new Date();
const start = new Date(end.getTime() - 90 * 86400000);
const formatDate = date => date.toISOString().slice(0,10).split('-').reverse().join('/');
const selicUrl='https://api.bcb.gov.br/dados/serie/bcdata.sgs.432/dados?formato=json&dataInicial='+encodeURIComponent(formatDate(start))+'&dataFinal='+encodeURIComponent(formatDate(end));
const economic_source=selic
 ?{id:'bcb_selic',url:selicUrl,publisher:'Banco Central do Brasil',kind:'selic'}
 :{id:'ibge_ipca',url:'https://servicodados.ibge.gov.br/api/v3/agregados/1737/periodos/-12/variaveis/63?localidades=N1%5Ball%5D',publisher:'IBGE',kind:'ipca'};
return {json:{briefing,economic_source}};

const {briefing,economic_source}= $('Selecionar fonte econômica').item.json;
const {id,url,publisher,kind}=economic_source;
const raw=$json.statusCode===200?String($json.body??$json.data??''):'';
let document='';
if(raw&&kind==='documento'){
 const article=raw.match(/<article\b[^>]*>([\s\S]*?)<\/article>/i)?.[1];
 const main=raw.match(/<main\b[^>]*>([\s\S]*?)<\/main>/i)?.[1];
 const html=article??main??(id==='planalto'?raw:'');
 document=html.replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1>/gi,' ').replace(/<[^>]+>/g,' ').replace(/&nbsp;/gi,' ').replace(/&quot;/gi,'"').replace(/&amp;/gi,'&').replace(/\s+/g,' ').trim();
}
if(raw&&kind!=='documento'){
 try{
  const data=JSON.parse(raw);
  if(kind==='selic'&&Array.isArray(data)){
   const points=data.filter(x=>/^\d{2}\/\d{2}\/\d{4}$/.test(x.data??'')&&/^\d+(?:\.\d+)?$/.test(x.valor??'')).sort((a,b)=>a.data.split('/').reverse().join('').localeCompare(b.data.split('/').reverse().join('')));
   document=points.filter((x,i)=>i===0||i===points.length-1||x.valor!==points[i-1].valor||x.valor!==points[i+1]?.valor).map(x=>x.data+' — Meta Selic: '+x.valor+'% ao ano').join('\n');
  }
  if(kind==='ipca'&&Array.isArray(data)){
   const series=data.find(x=>String(x.id)==='63')?.resultados?.flatMap(x=>x.series??[]).find(x=>String(x.localidade?.id)==='1')?.serie;
   document=Object.entries(series??{}).filter(([period,value])=>/^\d{6}$/.test(period)&&/^-?\d+(?:\.\d+)?$/.test(String(value))).sort().map(([period,value])=>period.slice(4)+'/'+period.slice(0,4)+' — Variação mensal do IPCA no Brasil: '+value+'%').join('\n');
  }
 }catch{}
}
return {json:{briefing,proposal:null,source:{id,url,publisher,text:document.slice(0,9500)},source_status:$json.statusCode??null}};

const {briefing,proposal,source}=$('Preparar material para apuração').item.json;
if($json.status!=='completed'||!/^gpt-6-luna(?:-\d{4}-\d{2}-\d{2})?$/.test($json.model??'')) throw Error('Apuração com gpt-6-luna indisponível ou incompleta.');
const parts=$json.output.flatMap(v=>v.content??[]).filter(v=>v.type==='output_text').map(v=>v.text);
const report=parts.length===1&&typeof parts[0]==='object'?parts[0]:JSON.parse(parts.join(''));
const findings=report.findings.filter(x=>typeof x.quote==='string'&&x.quote.trim().length>=12&&x.url===source.url&&source.text.includes(x.quote)).slice(0,6);
const questions=report.open_questions.filter(x=>typeof x==='string'&&x.trim()).map(x=>x.trim().slice(0,500)).slice(0,6);
return {json:{briefing:{...briefing,reporter_dossier:{status:findings.length?'apurado':'sem_achado',proposal,findings,open_questions:questions,source:findings.length?source:null,execution_id:String($execution.id)}}}};

const {briefing}=$json;
const text=[briefing.source.title,briefing.source.text].join('\n');
const matches=[...text.matchAll(/\b(PEC|PLP|PL)\s*(?:n[.º°o]+\s*)?([1-9]\d{0,5})\s*\/\s*(20\d{2}|19\d{2})\b/gi)];
const proposals=[...new Map(matches.map(([,type,number,year])=>[type.toUpperCase()+'/'+number+'/'+year,{type:type.toUpperCase(),number,year}])).values()];
if (proposals.length!==1) return {json:{briefing,proposal:null}};
return {json:{briefing,proposal:proposals[0]}};

const {briefing,proposal}=$('Identificar proposição').item.json;
const rows=$json.body?.dados;
const candidates=Array.isArray(rows)?rows.filter(x=>x.siglaTipo===proposal.type&&String(x.numero)===proposal.number&&String(x.ano)===proposal.year&&Number.isSafeInteger(x.id)&&x.id>0):[];
return {json:{briefing,proposal,official_id:candidates.length===1?candidates[0].id:null,lookup_status:$json.statusCode??null}};

const {briefing,official_id,proposal}=$('Conferir registro oficial').item.json;
const d=$json.body?.dados;
const text=d?.id===official_id?[
 ['Proposição', [d.siglaTipo,d.numero+'/'+d.ano].join(' ')],
 ['Ementa',d.ementa],['Apresentação',d.dataApresentacao],
 ['Data do último andamento registrado',d.statusProposicao?.dataHora],
 ['Descrição do último andamento registrado',d.statusProposicao?.descricaoTramitacao],
 ['Situação apresentada pela Câmara',d.statusProposicao?.descricaoSituacao],
 ['Despacho',d.statusProposicao?.despacho]
].filter(([,v])=>typeof v==='string'&&v.trim()).map(([k,v])=>k+': '+v.trim()).join('\n').slice(0,9500):'';
return {json:{briefing,proposal,source:{id:'camara_documental',publisher:'Câmara dos Deputados',url:'https://dadosabertos.camara.leg.br/api/v2/proposicoes/'+official_id,text},source_status:$json.statusCode??null}};
